begin;

do $$
declare
  v_sector uuid;
  v_primary uuid;
  v_treatment uuid;
  v_body jsonb;
  v_text text;
  v_id uuid;
begin
  select id into v_sector from public.sectors where slug='addiction-recovery';
  select id into v_primary from public.categories where slug='addiction-special-populations' and sector_id=v_sector;
  select id into v_treatment from public.categories where slug='addiction-treatment-care' and sector_id=v_sector;
  if v_sector is null or v_primary is null or v_treatment is null then raise exception 'accessible addiction care taxonomy missing'; end if;
  select id into v_id from public.content where slug='legacy-addiction-populations-disability-special-needs' and status='draft';
  if v_id is null then raise exception 'legacy disability draft missing or already migrated'; end if;

  v_body := jsonb_build_object('blocks', jsonb_build_array(
    jsonb_build_object('type','paragraph','text','الأشخاص ذوو الاحتياجات الخاصة والإعاقات قد يواجهون اضطرابات استخدام المواد مثل غيرهم، لكن الوصول إلى التقييم والعلاج والتعافي قد يصبح أصعب بسبب عوائق في المبنى والمعلومات والتواصل والنقل والتقنية ومواقف العاملين وتصميم الخدمة. المشكلة ليست أن الإعاقة تجعل العلاج أقل فاعلية تلقائيًا، بل أن نموذج الرعاية قد يفترض أن كل شخص يسمع ويرى ويقرأ ويتنقل ويتذكر ويتواصل ويتخذ القرار بالطريقة نفسها. المرجع الجيد يبدأ بإزالة هذه الافتراضات ثم يحافظ على معيار العلاج نفسه: سلامة، دليل، اختيار، خصوصية، استمرارية ونتائج قابلة للقياس.'),
    jsonb_build_object('type','paragraph','text','تؤكد منظمة الصحة العالمية أن الأشخاص ذوي الإعاقة لهم الحق في المستوى نفسه من جودة الرعاية الصحية، وأن الفجوات الصحية تنشأ جزئيًا من حواجز قابلة للتعديل داخل النظام الصحي. كما تنص اتفاقية حقوق الأشخاص ذوي الإعاقة على الوصول إلى خدمات الصحة دون تمييز وعلى أساس الموافقة الحرة والمستنيرة. في علاج الإدمان يعني ذلك أن التيسيرات المعقولة ليست خدمة إضافية تجميلية، بل جزء من قدرة الشخص على فهم الخيارات والوصول إلى الموعد والمشاركة في القرار والاستمرار في الخطة.'),

    jsonb_build_object('type','heading','level',2,'text','1. الإعاقة لا تساوي فقدان القدرة على الاختيار'),
    jsonb_build_object('type','paragraph','text','أحد أخطر الأخطاء هو افتراض أن وجود إعاقة معرفية أو حسية أو حركية أو نفسية يعني أن الأسرة أو الموظف يجب أن يتحدث بدل الشخص تلقائيًا. القدرة على اتخاذ قرار محدد تعتمد على طبيعة القرار وطريقة شرح المعلومات والدعم المتاح، وليست صفة ثابتة تُسحب بسبب تشخيص. يمكن تبسيط اللغة، تقسيم المعلومات، استخدام صور أو تواصل بديل، إعطاء وقت إضافي، وإشراك شخص داعم يختاره الفرد. الهدف زيادة قدرة الشخص على المشاركة بأقصى درجة ممكنة.'),
    jsonb_build_object('type','paragraph','text','قد يحتاج بعض الأشخاص إلى ترتيبات قانونية أو دعم قرار وفق النظام المحلي، لكن حتى عند وجود ولي أو مقدم رعاية يجب توجيه الكلام إلى الشخص نفسه واحترام تفضيلاته وخصوصيته بالقدر الذي يسمح به القانون والسلامة. لا ينبغي أن تتحول الحاجة إلى دعم إلى فقدان الصوت. ويحتاج الفريق إلى توثيق نوع الدعم الذي يساعد الشخص فعلًا بدل وضع عبارة عامة مثل صعوبة تعلم أو غير متعاون.'),

    jsonb_build_object('type','heading','level',3,'text','اسأل عن التيسير بدل افتراضه'),
    jsonb_build_object('type','paragraph','text','سؤال بسيط مثل ما الذي يجعل هذه الزيارة أسهل لك؟ قد يكشف حاجة إلى مترجم لغة إشارة، نص سهل القراءة، إضاءة أقل، كرسي مناسب، وقت أطول، مرافق، موعد في وقت محدد، استراحة حسية، أو وسيلة تواصل لا تعتمد على الكلام. لا توجد قائمة تناسب الجميع؛ شخصان بالتشخيص نفسه قد يحتاجان ترتيبات مختلفة. توثيق التيسير المفضل يمنع إعادة التفاوض عليه في كل زيارة.'),

    jsonb_build_object('type','heading','level',2,'text','2. خريطة الحواجز: أين يمكن أن يفشل الوصول قبل أن يبدأ العلاج؟'),
    jsonb_build_object('type','paragraph','text','تبدأ الإتاحة قبل باب العيادة. هل يستطيع الشخص العثور على معلومات مفهومة عن الخدمة؟ هل نموذج الحجز متوافق مع قارئ الشاشة؟ هل يمكن الحجز دون مكالمة صوتية لمن لا يستطيع استخدامها؟ هل المبنى والنقل ودورة المياه ومسار الحركة متاحان؟ هل توجد طريقة لاستدعاء المساعدة دون كشف غير ضروري للخصوصية؟ وهل يمكن الحصول على المعلومات بلغة أو صيغة مناسبة؟ كل حاجز من هذه الحواجز قد يظهر في السجل لاحقًا على أنه عدم التزام رغم أن المشكلة في التصميم.'),
    jsonb_build_object('type','paragraph','text','تضيف خدمات الإدمان حواجز خاصة: الوصمة، الخوف من فقدان دعم أسري أو سكن أو خدمة اجتماعية، اعتماد الشخص على مقدم رعاية يتحكم في النقل أو المال أو الدواء، أو قلق المؤسسة من التعامل مع احتياجات معقدة. لذلك لا يكفي أن تكون الخدمة متاحة فيزيائيًا؛ يجب أن تكون سياساتها واتصالاتها ومواعيدها وإحالاتها قابلة للاستخدام. منظمة الصحة العالمية تضع الإتاحة والتواصل المحترم والموافقة والتصميم الشامل والتقنيات الرقمية الميسرة ضمن مجالات تحسين عدالة الصحة للأشخاص ذوي الإعاقة.'),

    jsonb_build_object('type','heading','level',3,'text','حواجز شائعة يجب أن تسأل عنها المؤسسة'),
    jsonb_build_object('type','list','ordered',false,'items',jsonb_build_array(
      'الوصول الفيزيائي إلى المبنى وغرفة الفحص والحمام ومكان الانتظار.',
      'صيغ المعلومات: نص سهل، خط مناسب، صوت، ترجمة، لغة إشارة، قارئ شاشة أو تواصل بديل.',
      'الوقت: مدة الموعد، الحاجة إلى فواصل، وقت المعالجة والفهم والاستجابة.',
      'النقل والمرافقة والاعتماد على آخرين للوصول إلى الخدمة.',
      'البيئة الحسية مثل الضوضاء والإضاءة والازدحام والروائح.',
      'الخصوصية عندما يكون المرافق حاضرًا أو يعتمد الشخص عليه في حياته اليومية.',
      'التقنية الرقمية وكلمات المرور والتحقق والقدرة على استخدام الفيديو أو التطبيقات.',
      'التكلفة وتعدد المواعيد وتشتت الخدمات بين جهات مختلفة.'
    )),

    jsonb_build_object('type','heading','level',2,'text','3. التقييم الميسر: حافظ على المعنى وغيّر طريقة الوصول إليه'),
    jsonb_build_object('type','paragraph','text','لا ينبغي اختصار التقييم لأن التواصل أبطأ. ما يزال من المهم فهم نمط استخدام المواد، الأعراض، الوظيفة، الانسحاب والتسمم السابق، الصحة النفسية والجسدية، الأدوية، النوم والألم، التاريخ العلاجي، الدعم والأهداف. التكييف يكون في طريقة السؤال والوقت والوسائط، لا حذف مجالات أساسية. قد يساعد استخدام سؤال واحد في كل مرة، أمثلة ملموسة، جداول زمنية مرئية، إعادة صياغة ما فهمه الفريق، وطلب أن يشرح الشخص بطريقته ما اتفق عليه.'),
    jsonb_build_object('type','paragraph','text','بعض الأدوات القياسية للفحص لم تُختبر مع جميع الإعاقات أو أساليب التواصل. لذلك لا ينبغي تفسير الدرجة كحقيقة مستقلة عن المقابلة والسياق. إذا كان السؤال يعتمد على القراءة أو مفاهيم مجردة أو إدراك زمني معقد، فقد تتغير دقته. يجب تسجيل طريقة التيسير وأي حدود في التفسير، والاستعانة بمختص يعرف الإعاقة المعنية عندما يكون ذلك ضروريًا.'),

    jsonb_build_object('type','heading','level',3,'text','فرّق بين تغير خط الأساس وأثر المادة'),
    jsonb_build_object('type','paragraph','text','قد تكون لدى الشخص طريقة كلام أو حركة أو تواصل أو تنظيم حسي مختلفة في خطه الأساسي. على الفريق معرفة ما هو معتاد وما هو تغير جديد بدل تفسير كل اختلاف على أنه تسمم أو اضطراب نفسي. يساعد سؤال الشخص ومقدم الدعم الذي يختاره عن خط الأساس، مع عدم السماح للمرافق بإلغاء رواية الشخص. هذا مهم خصوصًا عندما توجد صعوبة في التواصل عن الألم أو الدوار أو القلق أو أعراض أخرى.'),

    jsonb_build_object('type','heading','level',2,'text','4. الأدوية والحالات الطبية: التنسيق أهم من الافتراض'),
    jsonb_build_object('type','paragraph','text','قد يستخدم الشخص أدوية للصرع أو الألم أو التشنج أو النوم أو الصحة النفسية أو أمراض مزمنة، وقد تزيد كثرة الأدوية صعوبة فهم الأعراض والتداخلات والالتزام. لا ينبغي إيقاف دواء أو تغييره ذاتيًا بسبب الخوف من الاعتماد، كما لا ينبغي افتراض أن كل عرض سببه الإدمان. يحتاج الفريق إلى قائمة دواء محدثة، جهة واضحة للمراجعة، وتنسيق بين علاج اضطراب استخدام المواد وبقية الرعاية.'),
    jsonb_build_object('type','paragraph','text','الألم مثال مهم. قد يكون حقيقيًا ومزمنًا ويؤثر في النوم والحركة والمزاج، ويمكن أن يتقاطع مع استخدام أدوية أو مواد. الرعاية الجيدة لا تختار بين تصديق الألم وعلاج اضطراب الاستخدام؛ تبني خطة متكاملة يقودها مختصون مناسبون. كذلك يمكن أن تؤثر مشكلات البلع أو الحركة الدقيقة أو الذاكرة على طريقة تناول الدواء أو تخزينه، ما يستدعي تيسيرات أو دعمًا عمليًا بدل تفسير المشكلة على أنها رفض للعلاج.'),

    jsonb_build_object('type','heading','level',2,'text','5. تكييف العلاج النفسي والسلوكي دون تفريغه من مضمونه'),
    jsonb_build_object('type','paragraph','text','يمكن تكييف كثير من التدخلات النفسية والسلوكية عبر تقليل التعقيد اللغوي، استخدام أمثلة ملموسة، صور وجداول، تكرار ومراجعة، جلسات أقصر أو فواصل، تمثيل المواقف عمليًا، وتدريب المهارات في البيئة الحقيقية. المهم هو معرفة المكون الفعال الذي يجب الحفاظ عليه. تحويل العلاج إلى نصائح عامة لأن الشخص لديه صعوبة معرفية يخفض الجودة بدل أن ييسرها.'),
    jsonb_build_object('type','paragraph','text','يحتاج المعالج أيضًا إلى فحص افتراضاته. السلوك الذي يبدو مقاومة قد يكون عدم فهم أو حملًا حسيًا زائدًا أو تعبًا أو صعوبة في الانتقال أو تجربة سابقة من الإهانة داخل النظام الصحي. يمكن سؤال الشخص عن الإيقاع والتواصل الذي يساعده وتغيير البيئة قبل استنتاج ضعف الدافعية. وإذا كانت هناك مهارات تنفيذية أو ذاكرة تحتاج دعمًا، يمكن ربط الخطة بتذكيرات ووسائط مناسبة ومقدم دعم بموافقة الشخص.'),

    jsonb_build_object('type','heading','level',3,'text','التواصل السهل لا يعني لغة طفولية'),
    jsonb_build_object('type','paragraph','text','اللغة الميسرة تستخدم جملًا واضحة ومفهومًا واحدًا في المرة وتشرح المصطلحات وتتحقق من الفهم، لكنها تحافظ على احترام عمر الشخص وخبرته. التحدث ببطء مبالغ أو استخدام نبرة طفولية أو مخاطبة المرافق بدل الشخص قد يقلل الثقة. وإذا كان الشخص يستخدم جهاز تواصل أو مترجمًا، يجب إعطاؤه وقتًا كاملًا وعدم افتراض أن التأخر في الإجابة يعني عدم المعرفة.'),

    jsonb_build_object('type','heading','level',2,'text','6. الصحة النفسية والاضطرابات النمائية المصاحبة'),
    jsonb_build_object('type','paragraph','text','قد تتقاطع اضطرابات استخدام المواد مع الاكتئاب والقلق والصدمات واضطراب فرط الحركة أو طيف التوحد أو إصابة دماغية أو اضطرابات معرفية. وجود تشخيص نمائي لا يلغي احتمال اضطراب نفسي مستقل، والعكس صحيح. التقييم يحتاج تسلسلًا زمنيًا، خطًا أساسيًا، تغير الوظيفة، أثر التسمم والانسحاب، ومعلومات من الشخص أولًا ثم مصادر إضافية بموافقته عندما تفيد.'),
    jsonb_build_object('type','paragraph','text','العلاج المتكامل يقلل خطر أن تُحال كل مشكلة إلى جهة مختلفة دون تنسيق. إذا كان فريق الإدمان لا يملك خبرة بإعاقة معينة، يمكن التعاون مع خدمات التأهيل أو الصحة النفسية أو الأعصاب أو الرعاية الأولية، مع بقاء خطة واحدة مفهومة ومسؤوليات واضحة. تعدد الجهات لا يجب أن يضاعف العبء على الشخص أو يجعله ناقل المعلومات الوحيد بين الفرق.'),

    jsonb_build_object('type','heading','level',2,'text','7. الخصوصية ودور الأسرة ومقدم الرعاية'),
    jsonb_build_object('type','paragraph','text','قد يكون المرافق ضروريًا للنقل أو التواصل أو الدعم اليومي، لكنه لا يحصل تلقائيًا على كل معلومات العلاج. يجب سؤال الشخص من يريد حضوره وما الذي يسمح بمشاركته، وإتاحة وقت خاص مع الفريق عندما يمكن ذلك وبطريقة آمنة. هذه الخطوة مهمة لاكتشاف أسئلة قد لا يستطيع الشخص طرحها أمام مقدم الرعاية أو حالات سيطرة مالية أو دوائية أو عنف أو استغلال.'),
    jsonb_build_object('type','paragraph','text','يمكن للأسرة أن تكون شريكًا قويًا عندما يختار الشخص ذلك: المساعدة في الروتين والمواعيد وفهم المعلومات وملاحظة تغيرات مهمة ودعم أهداف التعافي. لكن دورها ليس فرض خطة أو مراقبة كل تصرف. وإذا كانت الأسرة نفسها مرهقة، تحتاج خدمة مستقلة ودعمًا لحدودها ورفاهها. ينبغي للفريق أن يميز بين دعم القرار واستبدال القرار.'),

    jsonb_build_object('type','heading','level',3,'text','الحماية من الاستغلال والسيطرة'),
    jsonb_build_object('type','paragraph','text','قد يزيد الاعتماد على الآخرين في المال أو السكن أو النقل أو الأدوية التعرض للاستغلال. يجب أن تعرف الخدمة إجراءاتها المحلية عندما يصف الشخص سرقة أو تهديدًا أو حبسًا أو منع علاج أو إجباره على إعطاء المال أو الدواء. لا ينبغي مواجهة الشخص المسيطر بطريقة قد تزيد الخطر دون خطة مناسبة. الحماية جزء من الرعاية، ويجب أن تتبع القوانين والجهات المختصة في البلد.'),

    jsonb_build_object('type','heading','level',2,'text','8. خفض الضرر والمعلومات الصحية يجب أن تكون قابلة للوصول'),
    jsonb_build_object('type','paragraph','text','إذا قدم النظام معلومات عن الجرعة الزائدة أو العدوى أو الأدوية أو الطوارئ بصيغة لا يفهمها الشخص، فهو لم يقدمها فعليًا. ينبغي توفير رسائل مختصرة وميسرة وطرق تواصل مناسبة، وتدريب الشخص ومقدم الدعم الذي يختاره على كيفية الوصول إلى الخدمات المحلية عند الحاجة. هذه الصفحة لا تقدم تعليمات استخدام مواد؛ دورها التأكيد أن معلومات السلامة وخدمات الوقاية والفحص والعلاج يجب ألا تستبعد الأشخاص بسبب طريقة التواصل أو الحركة أو الفهم.'),
    jsonb_build_object('type','paragraph','text','تحتاج برامج المجتمع كذلك إلى إتاحة الأماكن والمواد الرقمية والمجموعات. مجموعة في طابق بلا مصعد أو جلسة فيديو بلا ترجمة أو نموذج إلكتروني لا يعمل بلوحة المفاتيح قد تستبعد شخصًا رغم إعلان الخدمة أنها مفتوحة للجميع. لذلك تدخل الإتاحة في تقييم جودة البرنامج من البداية لا بعد شكوى فردية.'),

    jsonb_build_object('type','heading','level',2,'text','9. الرعاية عن بعد والتقنية المساعدة'),
    jsonb_build_object('type','paragraph','text','يمكن للرعاية عن بعد أن تقلل عبء النقل وتسمح باستخدام أدوات مساعدة رقمية، لكنها ليست ميسرة تلقائيًا. يحتاج التصميم إلى توافق مع قارئات الشاشة والترجمة النصية أو لغة الإشارة، إمكان استخدام لوحة المفاتيح، تباين مناسب، نص واضح، بديل للصوت، وبديل للإنترنت الضعيف. كما يحتاج الشخص إلى مكان يوفر قدرًا مناسبًا من الخصوصية وقدرة على استخدام الجهاز.'),
    jsonb_build_object('type','paragraph','text','يحدد الفريق ما الذي يمكن إنجازه عن بعد وما الذي يحتاج حضورًا بسبب فحص طبي أو إجراء أو تقييم لا يمكن إتمامه بصورة كافية عبر الفيديو. ويجب ألا يصبح عدم قدرة الشخص على استخدام منصة بعينها سببًا لإغلاق الملف. التقنية أداة وصول، وإذا صنعت حاجزًا جديدًا فالمطلوب مسار بديل.'),

    jsonb_build_object('type','heading','level',2,'text','10. الانتقال بين الخدمات: لا تجعل الشخص يعيد بناء القصة كل مرة'),
    jsonb_build_object('type','paragraph','text','التنقل بين الطوارئ وعلاج الإدمان والرعاية الأولية والتأهيل والصحة النفسية والخدمات الاجتماعية قد يكون مرهقًا. انتقال جيد يحدد الجهة التالية والموعد والمسؤولية والمعلومات الضرورية والتيسيرات المطلوبة، مع موافقة مناسبة على مشاركة المعلومات. ينبغي ألا يكتشف الشخص عند كل باب أن المترجم أو الوصول الفيزيائي أو الدعم الذي يحتاجه غير متاح.'),
    jsonb_build_object('type','paragraph','text','يمكن استخدام جواز تواصل أو ملخص يختاره الشخص يتضمن طريقة التواصل والتيسيرات والأدوية والجهات الأساسية ومعلومات لا يريد تكرار شرحها، مع حماية الخصوصية. لا ينبغي أن يتحول هذا المستند إلى وصف ثابت يختزل الشخص أو يفتح معلومات أكثر من اللازم. القيمة في تسهيل الاستمرارية وتقليل الخطأ والعبء.'),

    jsonb_build_object('type','heading','level',2,'text','11. كيف تقيس المؤسسة عدالة وجودة الوصول؟'),
    jsonb_build_object('type','paragraph','text','القول إن الخدمة لا تميز لا يكفي. يمكن قياس نسبة من يطلبون تيسيرًا ويحصلون عليه، زمن الانتظار، إكمال أول موعد، الانقطاع، الانتقال بين الخدمات، الشكاوى المتعلقة بالإتاحة، واختلاف النتائج بحسب وجود احتياجات وصول عندما تسمح البيانات والخصوصية. كما يمكن إجراء تدقيق فعلي للمباني والنماذج والموقع والمنصة الرقمية والمواد المطبوعة.'),
    jsonb_build_object('type','paragraph','text','الأهم إشراك الأشخاص ذوي الاحتياجات الخاصة ومنظماتهم في التصميم والتقييم. منظمة الصحة العالمية تبني نهجها لعدالة الصحة على المشاركة وإدماج الإعاقة في الحوكمة والتخطيط والمراقبة، لا على إنشاء مسار منفصل لكل خدمة. عندما يُسأل المستخدمون فقط بعد تصميم البرنامج، تضيع فرصة إزالة الحاجز قبل أن يؤذي الوصول.'),

    jsonb_build_object('type','heading','level',3,'text','لوحة مؤشرات إتاحة عملية'),
    jsonb_build_object('type','list','ordered',false,'items',jsonb_build_array(
      'هل يمكن الوصول إلى معلومات الخدمة بأكثر من صيغة؟',
